    #[pyo3(signature = (*, region=None, profile=None, endpoint_url=None, config=None))]
    fn new(
        region: Option<String>,
        profile: Option<String>,
        endpoint_url: Option<String>,
        config: Option<RequestConfig>,
        py: Python<'_>,
    ) -> PyResult<Self> {
        let options = config.unwrap_or_default();
        options
            .validate()
            .map_err(|message| rboto_core::raise_core_error(py, "ConfigurationError", message))?;
        Ok(Self {
            state: Arc::new(ManagedResource::new(Arc::new(ClientState {
                config: ClientConfig {
                    region,
                    profile,
                    endpoint_url,
                    options,
                },
                client: OnceCell::new(),
            }))),
        })
    }

    fn _ensure_open(&self) -> PyResult<()> {
        if self.state.is_closed() {
            return Err(rboto_core::client_closed());
        }
        Ok(())
    }

    fn aclose<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        self.state.clone().aclose(py)
    }

    fn __aenter__<'py>(slf: Py<Self>, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        slf.borrow(py)._ensure_open()?;
        rboto_core::ready_future(py, slf.into_any())
    }

    fn __aexit__<'py>(
        &self,
        py: Python<'py>,
        _exc_type: &Bound<'py, PyAny>,
        _exc: &Bound<'py, PyAny>,
        _traceback: &Bound<'py, PyAny>,
    ) -> PyResult<Bound<'py, PyAny>> {
        self.aclose(py)
    }

